## 服务网格

对于更复杂的场景，可以考虑服务网格（如 Istio、Linkerd）：
- 自动服务发现
- 负载均衡
- 故障恢复
- 金丝雀发布
- 遥测和监控

using System;
using System.Net.Http;
using System.Threading.Tasks;
using Consul;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.CircuitBreaker;
using Polly.Extensions.Http;
using Polly.Timeout;

namespace MicroserviceCommunicationDemo
{
    // 服务发现
    public interface IServiceDiscovery
    {
        Task<string> GetServiceUrlAsync(string serviceName);
    }

    public class ConsulServiceDiscovery : IServiceDiscovery
    {
        private readonly IConsulClient _consulClient;
        private readonly ILogger<ConsulServiceDiscovery> _logger;

        public ConsulServiceDiscovery(IConsulClient consulClient, ILogger<ConsulServiceDiscovery> logger)
        {
            _consulClient = consulClient;
            _logger = logger;
        }

        public async Task<string> GetServiceUrlAsync(string serviceName)
        {
            var services = await _consulClient.Health.Service(serviceName, null, true);
            if (services.Response.Length == 0)
            {
                _logger.LogWarning($"服务 {serviceName} 未找到");
                return null;
            }

            // 简单轮询
            var service = services.Response[new Random().Next(services.Response.Length)];
            return $"http://{service.Service.Address}:{service.Service.Port}";
        }
    }

    // 弹性策略
    public static class ResiliencePolicies
    {
        public static IAsyncPolicy<HttpResponseMessage> GetRetryPolicy(ILogger logger)
        {
            return HttpPolicyExtensions
                .HandleTransientHttpError()
                .Or<TimeoutRejectedException>()
                .WaitAndRetryAsync(3,
                    retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)),
                    onRetry: (outcome, timespan, retryAttempt, context) =>
                    {
                        logger.LogWarning($"第 {retryAttempt} 次重试，等待 {timespan.TotalSeconds} 秒");
                    });
        }

        public static IAsyncPolicy<HttpResponseMessage> GetCircuitBreakerPolicy(ILogger logger)
        {
            return HttpPolicyExtensions
                .HandleTransientHttpError()
                .CircuitBreakerAsync(
                    handledEventsAllowedBeforeBreaking: 5,
                    durationOfBreak: TimeSpan.FromSeconds(30),
                    onBreak: (outcome, timespan) =>
                    {
                        logger.LogWarning($"熔断器打开，持续 {timespan.TotalSeconds} 秒");
                    },
                    onReset: () =>
                    {
                        logger.LogInformation("熔断器关闭");
                    });
        }

        public static IAsyncPolicy<HttpResponseMessage> GetTimeoutPolicy()
        {
            return Policy.TimeoutAsync<HttpResponseMessage>(TimeSpan.FromSeconds(10));
        }

        public static IAsyncPolicy<HttpResponseMessage> GetBulkheadPolicy(ILogger logger)
        {
            return Policy.BulkheadAsync<HttpResponseMessage>(
                maxParallelization: 10,
                maxQueuingActions: 25,
                onBulkheadRejectedAsync: context =>
                {
                    logger.LogWarning("请求被隔离策略拒绝");
                    return Task.CompletedTask;
                });
        }
    }

    // HttpClient 服务
    public class UserServiceClient
    {
        private readonly HttpClient _httpClient;
        private readonly ILogger<UserServiceClient> _logger;

        public UserServiceClient(HttpClient httpClient, ILogger<UserServiceClient> logger)
        {
            _httpClient = httpClient;
            _logger = logger;
        }

        public async Task<User> GetUserAsync(int id)
        {
            try
            {
                var response = await _httpClient.GetAsync($"/api/users/{id}");
                response.EnsureSuccessStatusCode();
                return await response.Content.ReadFromJsonAsync<User>();
            }
            catch (BrokenCircuitException)
            {
                _logger.LogError("熔断器已打开，无法获取用户");
                throw;
            }
        }
    }

    public class User
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Email { get; set; }
    }

    // API 网关配置
    public static class ApiGatewayExtensions
    {
        public static IServiceCollection AddApiGatewayServices(this IServiceCollection services)
        {
            // Consul 服务发现
            services.AddSingleton<IConsulClient>(sp =>
                new ConsulClient(c => c.Address = new Uri("http://localhost:8500")));
            services.AddSingleton<IServiceDiscovery, ConsulServiceDiscovery>();

            // HttpClient with Polly
            services.AddHttpClient<UserServiceClient>("user-service")
                .AddPolicyHandler((sp, request) =>
                {
                    var logger = sp.GetRequiredService<ILogger<UserServiceClient>>();
                    return ResiliencePolicies.GetRetryPolicy(logger);
                })
                .AddPolicyHandler((sp, request) =>
                {
                    var logger = sp.GetRequiredService<ILogger<UserServiceClient>>();
                    return ResiliencePolicies.GetCircuitBreakerPolicy(logger);
                })
                .AddPolicyHandler(ResiliencePolicies.GetTimeoutPolicy());

            return services;
        }

        public static async Task RegisterServiceAsync(
            this IApplicationBuilder app,
            string serviceName,
            string serviceId,
            string address,
            int port,
            string healthCheckUrl)
        {
            var consulClient = app.ApplicationServices.GetRequiredService<IConsulClient>();

            await consulClient.Agent.ServiceRegister(new AgentServiceRegistration
            {
                ID = serviceId,
                Name = serviceName,
                Address = address,
                Port = port,
                Check = new AgentServiceCheck
                {
                    HTTP = healthCheckUrl,
                    Interval = TimeSpan.FromSeconds(10),
                    Timeout = TimeSpan.FromSeconds(5)
                }
            });
        }

        public static async Task DeregisterServiceAsync(this IApplicationBuilder app, string serviceId)
        {
            var consulClient = app.ApplicationServices.GetRequiredService<IConsulClient>();
            await consulClient.Agent.ServiceDeregister(serviceId);
        }
    }

    // 使用示例
    public class OrderService
    {
        private readonly UserServiceClient _userClient;
        private readonly ILogger<OrderService> _logger;

        public OrderService(UserServiceClient userClient, ILogger<OrderService> logger)
        {
            _userClient = userClient;
            _logger = logger;
        }

        public async Task CreateOrderAsync(int userId, OrderItem[] items)
        {
            // 获取用户信息（带弹性策略）
            var user = await _userClient.GetUserAsync(userId);
            _logger.LogInformation($"为用户 {user.Name} 创建订单");

            // 创建订单逻辑
        }
    }

    public class OrderItem
    {
        public string ProductId { get; set; }
        public int Quantity { get; set; }
        public decimal Price { get; set; }
    }

    // 服务注册扩展
    public static class ServiceCollectionExtensions
    {
        public static IServiceCollection AddMicroserviceServices(this IServiceCollection services)
        {
            services.AddApiGatewayServices();
            services.AddScoped<OrderService>();
            return services;
        }
    }
}
